var data={eps:{est:1.42,act:1.58,fmt:function(v){return v.toFixed(2)},cons:'consensus 1.42 · 28 analysts'},rev:{est:89.24,act:91.80,fmt:function(v){return v.toFixed(2)+'B'},cons:'consensus 89.24B · 24 analysts'}};
var est=root.querySelector('[data-mkd7-est]'),act=root.querySelector('[data-mkd7-act]'),chip=root.querySelector('[data-mkd7-chip]'),fill=root.querySelector('[data-mkd7-fill]'),cons=root.querySelector('[data-mkd7-cons]');
var btns=root.querySelectorAll('[data-mkd7-m]');
function show(key){
  var d=data[key];
  var pct=(d.act-d.est)/d.est*100;
  est.textContent=d.fmt(d.est);act.textContent=d.fmt(d.act);
  var beat=pct>=0;
  chip.textContent=(beat?'▲ BEAT +':'▼ MISS ')+pct.toFixed(1)+'%';
  chip.classList.toggle('mkd7-earnings-row__chip--miss',!beat);
  cons.textContent=d.cons;
  var w=Math.min(50,Math.abs(pct)/20*50);
  fill.classList.toggle('mkd7-earnings-row__fill--miss',!beat);
  fill.style.left=(beat?50:50-w)+'%';
  fill.style.width=w+'%';
}
for(var i=0;i<btns.length;i++){
  btns[i].addEventListener('click',function(e){
    for(var j=0;j<btns.length;j++){
