      btns[j].classList.toggle('mkd7-earnings-row__sb--on',on);
      btns[j].setAttribute('aria-pressed',on?'true':'false');
    }
    show(e.currentTarget.getAttribute('data-mkd7-m'));
  });
}
fill.style.width='0';
requestAnimationFrame(function(){show('eps')});

var cd=root.querySelector('[data-mkd7-cd]');
if(cd){
  var left=26*60+14;
  var tick=function(){
    left--;
    if(left<=0){cd.textContent='RELEASING';return}
    var m=Math.floor(left/60),s=left%60;
    cd.textContent=(m<10?'0':'')+m+':'+(s<10?'0':'')+s;
  };
  setInterval(tick,1000);
}

