var body=root.querySelector('[data-mkd7-body]');
var btns=root.querySelectorAll('[data-mkd7-key]');
var rm=window.matchMedia('(prefers-reduced-motion: reduce)');
var cur='chg',asc=false;
function num(r,k){return parseFloat(r.getAttribute('data-mkd7-'+k))}
function run(key,up){
  var rows=Array.prototype.slice.call(body.children);
  rows.forEach(function(r){r._mkd7Top=r.getBoundingClientRect().top});
  rows.sort(function(a,b){
    var d=key==='sym'?a.getAttribute('data-mkd7-sym').localeCompare(b.getAttribute('data-mkd7-sym')):num(a,key)-num(b,key);
    return up?d:-d;
  });
  rows.forEach(function(r){body.appendChild(r)});
  if(!rm.matches){
    rows.forEach(function(r){
      var d=r._mkd7Top-r.getBoundingClientRect().top;
      r.style.transition='none';
      r.style.transform=d?'translateY('+d+'px)':'';
    });
    void body.offsetWidth;
    rows.forEach(function(r){
      r.style.transition='transform .34s cubic-bezier(.2,.7,.3,1)';
      r.style.transform='';
    });
  }
  for(var i=0;i<btns.length;i++){
    var b=btns[i],k=b.getAttribute('data-mkd7-key'),ar=b.querySelector('[data-mkd7-ar]');
    if(k===key){b.parentNode.setAttribute('aria-sort',up?'ascending':'descending');ar.textContent=up?'▲':'▼';}
    else{b.parentNode.setAttribute('aria-sort','none');ar.textContent='·';}
  }
}
for(var i=0;i<btns.length;i++){
  btns[i].addEventListener('click',function(e){
    var k=e.currentTarget.getAttribute('data-mkd7-key');
    asc=(k===cur)?!asc:(k==='sym');
    cur=k;
    run(k,asc);
  });
}

