var tiles=root.querySelectorAll('[data-mkd7-k]');
var read=root.querySelector('[data-mkd7-read]');
var segs=root.querySelectorAll('[data-mkd7-h]');
var data={d:{tech:1.24,fin:-0.31,comm:0.82,hlth:-0.64,engy:2.10,disc:0.45,util:-0.88,indu:-0.12},w:{tech:3.86,fin:1.12,comm:-0.94,hlth:-2.31,engy:5.42,disc:0.08,util:-1.75,indu:0.63}};
var wt={tech:32.1,fin:13.4,comm:9.8,hlth:11.2,engy:3.9,disc:10.3,util:2.4,indu:8.2};
var horizon='d';
function paint(){
  var v=data[horizon],up=0,dn=0,br=0,tw=0;
  for(var i=0;i<tiles.length;i++){
    var t=tiles[i],k=t.getAttribute('data-mkd7-k'),val=v[k];
    var a=Math.min(0.62,0.1+Math.abs(val)/3*0.52).toFixed(3);
    t.style.setProperty('--mkd7h-c',val>=0?'39,208,127':'255,96,114');
    t.style.setProperty('--mkd7h-a',a);
    t.querySelector('[data-mkd7-p]').textContent=(val>=0?'▲ +':'▼ −')+Math.abs(val).toFixed(2)+'%';
    t.setAttribute('aria-label',t.getAttribute('data-mkd7-name')+' '+(val>=0?'up ':'down ')+Math.abs(val).toFixed(2)+' percent');
    if(val>=0){up++}else{dn++}
    br+=val*wt[k];tw+=wt[k];
  }
  read.textContent=up+' up / '+dn+' down · breadth '+(br/tw>=0?'+':'−')+Math.abs(br/tw).toFixed(2)+'% cap-weighted';
}
function detail(t){
  var k=t.getAttribute('data-mkd7-k'),val=data[horizon][k];
  read.textContent=t.getAttribute('data-mkd7-name')+' · '+(val>=0?'▲ +':'▼ −')+Math.abs(val).toFixed(2)+'% · '+wt[k]+'% of index';
}
for(var i=0;i<tiles.length;i++){
  tiles[i].addEventListener('mouseenter',function(e){detail(e.currentTarget)});
  tiles[i].addEventListener('focus',function(e){detail(e.currentTarget)});
  tiles[i].addEventListener('mouseleave',paint);
  tiles[i].addEventListener('blur',paint);
}
for(var j=0;j<segs.length;j++){
  segs[j].addEventListener('click',function(e){
    horizon=e.currentTarget.getAttribute('data-mkd7-h');
    for(var m=0;m<segs.length;m++){
      var on=segs[m]===e.currentTarget;
      segs[m].classList.toggle('mkd7-sector-heat__sb--on',on);
      segs[m].setAttribute('aria-pressed',on?'true':'false');
    }
    paint();
  });
}
paint();
